PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS graph_epochs(graph_epoch INTEGER PRIMARY KEY,unified_epoch INTEGER NOT NULL,derivation_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('STAGED','CURRENT','STALE','CONFLICT')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS graph_publication_state(surface_key TEXT PRIMARY KEY CHECK(surface_key='CURRENT'),graph_epoch INTEGER NOT NULL,unified_epoch INTEGER NOT NULL,contract_sha256 TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('CURRENT','DEGRADED','CONFLICT','STALE')),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(node_id TEXT PRIMARY KEY,semantic_ref TEXT NOT NULL UNIQUE,node_type TEXT NOT NULL,label TEXT NOT NULL,epistemic_class TEXT NOT NULL,source_unified_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS edges(edge_id TEXT PRIMARY KEY,from_node TEXT NOT NULL REFERENCES nodes(node_id),to_node TEXT NOT NULL REFERENCES nodes(node_id),relation_type TEXT NOT NULL,weight REAL NOT NULL,evidence_class TEXT NOT NULL,source_unified_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,status TEXT NOT NULL,provenance_clay TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_edges_from ON edges(from_node,status);
CREATE INDEX IF NOT EXISTS idx_edges_to ON edges(to_node,status);
CREATE TABLE IF NOT EXISTS activation_channels(node_id TEXT NOT NULL REFERENCES nodes(node_id),channel TEXT NOT NULL,value REAL NOT NULL,source_ref TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(node_id,channel,source_ref));
CREATE TABLE IF NOT EXISTS hyperbindings(binding_id TEXT PRIMARY KEY,members_clay TEXT NOT NULL,required_count INTEGER NOT NULL,joint_score REAL NOT NULL,pairwise_baseline REAL NOT NULL,synergy REAL NOT NULL,persistence REAL NOT NULL,transfer REAL NOT NULL,causal_contribution REAL NOT NULL,provenance_count INTEGER NOT NULL,false_binding_risk REAL NOT NULL,status TEXT NOT NULL,evidence_clay TEXT NOT NULL,graph_epoch INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hyperbinding_member_index(member_ref TEXT NOT NULL,binding_id TEXT NOT NULL REFERENCES hyperbindings(binding_id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'MEMBER',graph_epoch INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(member_ref,binding_id));
CREATE INDEX IF NOT EXISTS idx_hb_member_current ON hyperbinding_member_index(member_ref,status);
CREATE TABLE IF NOT EXISTS candidate_sets(candidate_set_id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL,intent_clay TEXT NOT NULL,source_unified_epoch INTEGER NOT NULL,graph_epoch INTEGER NOT NULL,candidate_universe_hash TEXT NOT NULL,hot_path_receipt_clay TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS candidate_members(candidate_set_id TEXT NOT NULL REFERENCES candidate_sets(candidate_set_id) ON DELETE CASCADE,semantic_ref TEXT NOT NULL,lane TEXT NOT NULL CHECK(lane IN ('KNOWN','ANALOGOUS','COUNTERINTUITIVE','EMERGENT_NOVEL')),fit REAL NOT NULL,novelty REAL NOT NULL,evidence REAL NOT NULL,risk REAL NOT NULL,score REAL NOT NULL,reason_clay TEXT NOT NULL,PRIMARY KEY(candidate_set_id,semantic_ref,lane));
CREATE TABLE IF NOT EXISTS graph_conflicts(conflict_id TEXT PRIMARY KEY,left_ref TEXT NOT NULL,right_ref TEXT NOT NULL,conflict_kind TEXT NOT NULL,state TEXT NOT NULL,evidence_clay TEXT NOT NULL,graph_epoch INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topology_intervention_handles(handle_id TEXT PRIMARY KEY,target_ref TEXT NOT NULL,intervention_classes_clay TEXT NOT NULL,rollback_recipe_clay TEXT NOT NULL,graph_epoch INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
